public static void render(CT_PageBlock layer, Div<?> e, AtomicInteger maxUnitID) {
        final int[] bgColor = e.getBackgroundColor();
        if (bgColor == null && e.isNoBorder()) {
            // 没有背景颜色没有边框，那么这个Div就不需要绘制
            return;
        }

        // 图元透明度
        Integer alpha = null;
        if (e.getOpacity() != null) {
            alpha = (int) (e.getOpacity() * 255);
        }

        if (e.getHeight() == null) {
            throw new IllegalArgumentException("Div元素的高度必须指定");
        }

        Double borderTop = e.getBorderTop();
        Double borderRight = e.getBorderRight();
        Double borderBottom = e.getBorderBottom();
        Double borderLeft = e.getBorderLeft();

        /*
           基础的盒式模型绘制：
            1. 首先绘制背景颜色
            2. 绘制边框
         */
        // 背景颜色 (又背景颜色并且，内容存在高度)
        double eleContentHeight = e.getPaddingTop() + e.getHeight() + e.getPaddingBottom();

        if (bgColor != null && eleContentHeight > 0) {
            ST_ID objId = new ST_ID(maxUnitID.incrementAndGet());
            PathObject bg = new PathObject(objId);
            double x = e.getX() + e.getMarginLeft() + borderLeft;
            double y = e.getY() + e.getMarginTop() + borderTop;
            double w = e.getPaddingLeft() + e.getWidth() + e.getPaddingRight();
            bg.setBoundary(x, y, w, eleContentHeight)
                    // 设置填充颜色的矩形区域
                    .setAbbreviatedData(GraphHelper.rect(0, 0, w, eleContentHeight))
                    // 设置不描边、填充，并且设置填充颜色
                    .setStroke(false)
                    .setFill(true)
                    .setFillColor(CT_Color.rgb(bgColor));
            if (alpha != null) {
                bg.setAlpha(alpha);
            }
            // 加入图层
            layer.addPageBlock(bg);
        }

        /*
            边框的绘制有两种情况:
                1. 4条边宽度都一致。
                2. 4条边宽度不一致。
         */

        // 虚线边框样式：[偏移量,虚线长,空白长, 虚线长,空白长, 虚线长,空白长, 虚线长,空白长, ...]
        Double[] borderDash = e.getBorderDash();

        // 4条边宽度都一致，那么直接定位并且绘制
        if (eq(borderTop, borderRight, borderBottom, borderLeft)) {
            double lineWidth = borderTop;
            ST_ID objId = new ST_ID(maxUnitID.incrementAndGet());
            PathObject border = new PathObject(objId);
            double x = e.getX() + e.getMarginLeft();
            double y = e.getY() + e.getMarginTop();
            double w = lineWidth + e.getPaddingLeft() + e.getWidth() + e.getPaddingRight() + lineWidth;
            double h = lineWidth + e.getPaddingTop() + e.getHeight() + e.getPaddingBottom() + lineWidth;
            border.setBoundary(x, y, w, h)
                    .setLineWidth(lineWidth)
                    .setAbbreviatedData(GraphHelper.rect(
                            lineWidth / 2, lineWidth / 2,
                            w - lineWidth,
                            h - lineWidth));
            // 如果存在边框颜色，那么设置颜色；默认颜色为 黑色
            int[] borderColor = e.getBorderColor();
            if (borderColor != null) {
                border.setStrokeColor(CT_Color.rgb(borderColor));
            }
            if (alpha != null) {
                border.setAlpha(alpha);
            }
            if (borderDash != null) {
                setLineDash(border, borderDash);
            }
            layer.addPageBlock(border);
        }
        // 4条边宽度不一致，需要分别绘制各条边
        else {
            /*
                顶边
             */
            double topWidth = borderTop;
            double ZERO  = 0.00001;
            if (topWidth > ZERO) {
                ST_ID objId = new ST_ID(maxUnitID.incrementAndGet());
                PathObject topBorder = new PathObject(objId);
                double x = e.getX() + e.getMarginLeft();
                double y = e.getY() + e.getMarginTop();
                double w = borderLeft + e.getPaddingLeft() + e.getWidth() + e.getPaddingRight() + borderRight;
                topBorder.setBoundary(x, y, w, topWidth)
                        .setLineWidth(topWidth)
                        .setAbbreviatedData(new AbbreviatedData().M(0, topWidth / 2).L(w, topWidth / 2));
                int[] borderColor = e.getBorderColor();
                if (borderColor != null) {
                    topBorder.setStrokeColor(CT_Color.rgb(borderColor));
                }
                if (alpha != null) {
                    topBorder.setAlpha(alpha);
                }
                if (borderDash != null) {
                    setLineDash(topBorder, borderDash);
                }
                layer.addPageBlock(topBorder);
            }
            /*
                底边
             */
            double bottomWidth = borderBottom;
            if (bottomWidth > ZERO) {
                ST_ID objId = new ST_ID(maxUnitID.incrementAndGet());
                PathObject bottomBorder = new PathObject(objId);
                double x = e.getX() + e.getMarginLeft();
                double y = e.getY()
                        + e.getMarginTop()
                        + borderTop
                        + e.getPaddingTop()
                        + e.getHeight()
                        + e.getPaddingBottom();
                double w = borderLeft + e.getPaddingLeft() + e.getWidth() + e.getPaddingRight() + borderRight;
                bottomBorder.setBoundary(x, y, w, bottomWidth)
                        .setLineWidth(bottomWidth)
                        .setAbbreviatedData(new AbbreviatedData().M(0, bottomWidth / 2).L(w, bottomWidth / 2));
                int[] borderColor = e.getBorderColor();
                if (borderColor != null) {
                    bottomBorder.setStrokeColor(CT_Color.rgb(borderColor));
                }
                if (alpha != null) {
                    bottomBorder.setAlpha(alpha);
                }
                if (borderDash != null) {
                    setLineDash(bottomBorder, borderDash);
                }
                layer.addPageBlock(bottomBorder);
            }
            // 元素中没有任何内容和边框，那么认为是占位符，跳过绘制
            if ((topWidth + bottomWidth + eleContentHeight) == 0) {
                return;
            }
            /*
                左边
             */
            double leftWidth = borderLeft;
            if (leftWidth > ZERO) {
                ST_ID objId = new ST_ID(maxUnitID.incrementAndGet());
                PathObject leftBorder = new PathObject(objId);
                double x = e.getX() + e.getMarginLeft();
                double y = e.getY() + e.getMarginTop() + topWidth;
                double h = borderTop + e.getPaddingTop()
                        + e.getHeight() + e.getPaddingBottom() + borderBottom
                        - topWidth - bottomWidth;
                leftBorder.setBoundary(x, y, leftWidth, h)
                        .setLineWidth(leftWidth)
                        .setAbbreviatedData(new AbbreviatedData().M(leftWidth / 2, 0).L(leftWidth / 2, h));
                int[] borderColor = e.getBorderColor();
                if (borderColor != null) {
                    leftBorder.setStrokeColor(CT_Color.rgb(borderColor));
                }
                if (alpha != null) {
                    leftBorder.setAlpha(alpha);
                }
                if (borderDash != null) {
                    setLineDash(leftBorder, borderDash);
                }
                layer.addPageBlock(leftBorder);
            }

            /*
                右边
             */
            double rightWidth = borderRight;
            if (rightWidth > ZERO) {
                ST_ID objId = new ST_ID(maxUnitID.incrementAndGet());
                PathObject rightBorder = new PathObject(objId);
                double x = e.getX()
                        + e.getMarginLeft()
                        + borderLeft
                        + e.getPaddingLeft()
                        + e.getWidth()
                        + e.getPaddingRight();
                double y = e.getY() + e.getMarginTop() + topWidth;
                double h = borderTop + e.getPaddingTop()
                        + e.getHeight() + e.getPaddingBottom() + borderBottom
                        - topWidth - bottomWidth;
                rightBorder.setBoundary(x, y, rightWidth, h)
                        .setLineWidth(rightWidth)
                        .setAbbreviatedData(new AbbreviatedData().M(rightWidth / 2, 0).L(rightWidth / 2, h));
                int[] borderColor = e.getBorderColor();
                if (borderColor != null) {
                    rightBorder.setStrokeColor(CT_Color.rgb(borderColor));
                }
                if (alpha != null) {
                    rightBorder.setAlpha(alpha);
                }
                if (borderDash != null) {
                    setLineDash(rightBorder, borderDash);
                }
                layer.addPageBlock(rightBorder);
            }
        }
    }

public static void render(CT_PageBlock layer, ResManager resManager, Paragraph e, AtomicInteger maxUnitID) {
        if (e == null) {
            return;
        }
        LinkedList<TxtLineBlock> lines = e.getLines();
        // 段落中没有任何内容，那么跳过不渲染
        if (lines == null || lines.isEmpty()) {
            // 直接加入到虚拟页面的段落对象是经过预处理的，所以此处尝试预处理。
            e.doPrepare(e.getWidth() + e.widthPlus());
            lines = e.getLines();
            if (lines == null || lines.isEmpty()) {
                // 如果还是没有行，那么是个空段落，跳过
                return;
            }
        }

        // 可容纳元素的总高度
        Double containerHeight = e.getHeight();
        /*
        每一行左上角坐标
         */
        double lineTopX = e.getX() + e.getMarginLeft() + e.getBorderLeft() + e.getPaddingLeft();
        double offsetY = e.getY() + e.getMarginTop() + e.getBorderTop() + e.getPaddingTop();
        // 已经写入的元素高度统计
        double hCount = 0;
        // 渲染每一行文字
        for (TxtLineBlock txtLine : lines) {
            // 行内的X偏移量为行开头
            double offsetX;
            // 根据浮动方式确定起始字符坐标
            switch (txtLine.getTextAlign()) {
                case right:
                    offsetX = lineTopX + (txtLine.getLineMaxAvailableWidth() - txtLine.getWidth());
                    break;
                case center:
                    offsetX = lineTopX + (txtLine.getLineMaxAvailableWidth() - txtLine.getWidth()) / 2;
                    break;
                case left:
                default:
                    offsetX = lineTopX;
                    break;
            }

            // 一行内的所有Span的图元高度都为行高度（最高文字高度 + 行间距）
            double h = txtLine.getHeight();
            if (hCount + h > containerHeight) {
                // 如果文字内容高度大于容纳文字的容器高度，那么将该部分内容舍弃，不渲染。
                break;
            }

            // 遍历行内的每个Span
            for (Span s : txtLine.getInlineSpans()) {
                // 文字图元宽度
                double w = s.blockSize().getWidth();
                if (w == 0) {
                    // 空行
                    continue;
                }
                if (s instanceof PlaceholderSpan) {
                    // 忽略占位符的渲染只进行坐标偏移
                    offsetX += w;
                    continue;
                }

                // 将字体加入到资源中
                ST_ID id = null;
                try {
                    id = resManager.addFont(s.getFont());
                } catch (IOException ex) {
                    throw new RenderException("渲染异常，字体复制失败：" + ex.getMessage(), ex);
                }
                // 新建字体对象
                TextObject txtObj = new TextObject(maxUnitID.incrementAndGet());
                ST_Box boundary = new ST_Box(offsetX, offsetY, w, h);
                txtObj.setBoundary(boundary)
                        // 设置字体ID
                        .setFont(id.ref())
                        // 设置字体大小
                        .setSize(s.getFontSize());
                // 设置字体粗细
                if (s.getWeight() != null) {
                    txtObj.setWeight(s.getWeight());
                } else if (s.isBold()) {
                    txtObj.setWeight(Weight.W_800);
                }

                // 是否是斜体
                if (s.isItalic()) {
                    txtObj.setItalic(true);
                }
                // 是否填充，默认为true表示填充
                if (!s.isFill()) {
                    txtObj.setFill(false);
                }
                // 设置字体颜色，默认颜色为黑色
                int[] color = s.getColor();
                if (color != null && color.length >= 3) {
                    txtObj.setFillColor(CT_Color.rgb(color));
                }
                // 创建OFD文字定位对象
                Double offset = txtLine.getMaxSpanHeight();
                TextCode tcSTTxt = new TextCode()
                        // 定位点位于文字的左下角，文字文字Y偏移量为该行最高文字的高度
                        .setCoordinate(0d, offset)
                        .setContent(s.getText());
                Double[] deltaX = s.getDeltaX();
                if (deltaX.length > 0) {
                    // 如果多余一个字符那么需要设置字符偏移量
                    tcSTTxt.setDeltaX(deltaX);
                }
                // 加入到字符对象中
                txtObj.addTextCode(tcSTTxt);
                if (e.getOpacity() != null) {
                    // 图元透明度
                    txtObj.setAlpha((int) (e.getOpacity() * 255));
                }
                // 将文字对象加入到图层
                layer.addPageBlock(txtObj);
                // 是否包含下划线
                if (s.isUnderline()) {
                    ST_ID underlineId = new ST_ID(maxUnitID.incrementAndGet());
                    // 构造下划线
                    double underlineOffset = offset + s.getUnderlineOffset();
                    double underlineWidth = s.getUnderlineWidth();
                    if (underlineWidth == 0) {
                        // 0.05 比例系数为经验值
                        underlineWidth = s.getFontSize() * 0.05;
                    }
                    PathObject underline = drawUnderline(underlineId, boundary, color, underlineOffset, underlineWidth);
                    if (e.getOpacity() != null) {
                        // 图元透明度
                        underline.setAlpha((int) (e.getOpacity() * 255));
                    }
                    // 加入到文字对象的上方
                    layer.addPageBlock(underline);
                }
                // 计算行内下一个图元的X坐标
                offsetX += w;
            }
            offsetY += h;
            hCount += h;
        }
    }

